from collections import defaultdict

def solve(N, segments):
    # Initialize countDict for red count
    countDict = defaultdict(int)
    countDict[0] = 0
    answer = [0 for _ in range(N)]

    for i in range(N):
        # Use Filter to find segments that contain the current segment [li, ri]
        redSegmentsInSegmentOnePass = filter(lambda x: x[0] <= segments[i][0] <= segments[i][1], segments)
        for redSegment in redSegmentsInSegmentOnePass:
            if countDict[redSegment[0]] - countDict[redSegment[1]] <= 1:
                countDict[redSegment[0]] -= 1
                countDict[redSegment[1]] += 1
            else:
                return [-1]

        # Try all blue segments that contain the current segment [li, ri]
        blueSegmentOnePass = filter(lambda x: x[0] <= segments[i][0] <= segments[i][1], segments)
        for blueSegment in blueSegmentOnePass:
            for k in range(len(redSegmentsInSegmentOnePass)):
                if (redSegmentsInSegmentOnePass[k][1] + 1) < blueSegment[0] < (blueSegment[1] - 1):
                    if countDict[blueSegment[0]] - countDict[blueSegment[1]] == 1:
                        countDict[blueSegment[0]] -= 1
                        countDict[blueSegment[1]] += 1
                    elif countDict[blueSegment[0]] > countDict[blueSegment[1]]:
                        countDict.pop(blueSegment[1])
                    else:
                        countDict.pop(blueSegment[0])
                    break

        # If there are no remaining blue segments to try, return [-1]
        if len(countDict) == 0:
            return [-1]
        answer[i] = 0 if blueSegmentOnePass == [] else 1

    return answer

