def prime_factorization(n, p):
    if n < 1:
        return []
    primes = []
    while p * p <= n:
        if n % p:
            p += 1
        else:
            n //= p
            primes.append(p)
    if n > 1:
        primes.append(n)
    return primes

def find_union_size(n, m, p, a, b):
    # Convert b into its prime factors
    b_factors = {}
    for bi in b:
        for factor in prime_factorization(bi, p):
            b_factors.setdefault(factor, 0)
            b_factors[factor] += 1

    # Set to hold union sizes
    union_sizes = set()

    # Start with set {1}
    union_sizes.add(1)

    for ai in a:
        new_union_sizes = set()

        for size in union_sizes:
            if all((b * ai) % p not in size for b in b_factors):
                new_size = size * (b_factors[p % b < p for b in b_factors] + 1)
                if new_size != 1:
                    new_union_sizes.add(int(pow(new_size * 26, n // size, p)))

        union_sizes.update(new_union_sizes)

    return len(union_sizes)

