import sys
from typing import List

def max_asterisks_eaten(n: int, chars: List[str]) -> (int, int):
    # Check if the line starts with an asterisk
    if chars[0] == '*':
        return (0, 0)

    max_asterisks = [0] * n
    min_time = sys.maxsize

    # State initialization: 1: Mine, -1: Empty, Other: Moving
    state = [-1] * n

    # Determine the first cell that needs to be processed in state 0, 1
    index = 0
    for i in range(1, n + 1):
        if chars[i - 1] == '.' and chars[i - 2] == '.':
            true_index = (i * 2 - 3) % (i - 1) + 1
            if i > true_index:
                state[index] = 1
                index += 1
        if chars[i - 1] == 'P':
            state[i - 1] = 0

    # DP table for times; dp[i][0]: Smallest time if already at truth value at position i
    dp = [[sys.maxsize] * 2 for _ in range(n + 1)]
    dp[0][0] = 0
    i, j = 0, 0

    while state[i] != -1:
        if state[i] == 1 and chars[i] == '.':
            dp[i][j] = dp[i][j^0] + 1
        elif state[i] == -1:
            dp[i][j] = max(dp[i][j^0], dp[i-1][j^1])
            if chars[i] == '*':
                dp[i][j] += 1
        elif chars[i-1] == '.' and chars[i-2] == '.':
            res = (i * 2 - 3) % (i - 1) + 1
            if i > res:
                dp[i][j] = dp[res][j^1] + 1
            else:
                dp[i][j] = max(dp[i][j^1], dp[i-1][j^0] + 1)
        else:
            dp[i][j] = max(dp[i][j^0], dp[i-1][j^1])
        j = (j - 1) % 2
        i += state[i]

    return max(dp[i]), dp[i][1]

