from collections import defaultdict

class Tree:
    def __init__(self, n):
        self.n = n
        self.tree = [[] for _ in range(n)]

    def add_edge(self, u, v):
        self.tree[u].append(v)
        self.tree[v].append(u)

    def dfs(self, node, parent, path):
        for neighbor in self.tree[node]:
            if neighbor != parent:
                self.dfs(neighbor, node, path)
                MEX = max(path[neighbor], MEX)

    def query(self, type, i, j):
        path = [i] * self.n
        self.dfs(i, -1, path)
        if type == 1:
            path[i], path[j] = path[j], path[i]
        result = max(max(path[u] for u in self.tree[i]) - path[i] for i in range(self.n))
        return result + 1 if MEX > result else MEX

