from collections import deque

def delete_palindrome(string, points, n):
    used = [False] * n
    for i in range(n):
        for j in range(i, n):
            if is_palindrome(string[i:j+1]):
                if not used[j-i+1]:
                    used[j-i+1] = True
                    points[j-i+1] = max(points[j-i+1], i + 1)

    best_points = 0
    queue = deque()
    queue.append((0, 0))
    while queue:
        current = queue.popleft()
        if current[0] == n:
            best_points = max(best_points, current[1])
        else:
            for k in range(abs(current[0]) + 1, min(current[0] + n, n - current[0])):
                if not used[k + current[0]]:
                    used[k + current[0]] = True
                    points[k + current[0]] = max(points[k + current[0]], points[current[0]] + 1)
                    atk = k + current[0]
                    opp = n - k - 1
                    if opp > atk:
                        queue.append((opp, points[current[0]] + opp - atk))
                    if opp < atk:
                        queue.append((atk, points[current[0]] + atk - opp))
    return best_points

def is_palindrome(s):
    return s == s[::-1]

