            return points
        index = (len(points) - 1) // 2
        pivot = points[index]
        return [
            kdtree([p for i, p in enumerate(points) if i < index or (i == index and p[0] < pivot[0])])
            + kdtree([p for i, p in enumerate(points) if i > index])
        ]

    def closest(point, points):
        if len(points) <= 1:
            return [-1, -1, 0 if len(points) > 0 else inf]
        if len(points) == 2:
            return [point] + points
        left = kdtree(points[:])
        center = left[len(left) // 2]
