    return a * b // gcd(a, b)

def problem(n, m, p, a, b):
    capacities = [1]
    for i in range(1, n + m + 1):
        capacity = lcm(capacities[0], i) * a[i - 1] % p
        if capacity not in capacities:
            capacities.append(capacity)

    unique_groups_count = 0
    for group in capacities:
        checked = set()
        stack = [group]
        while stack:
            current = stack.pop()
            if current in checked:
                continue
            checked.add(current)
            next_group = current * a[-1] % p
            if next_group not in checked and next_group not in capacities:
                if next_group > 1:
                    unique_groups_count += 1
                stack.extend([next_group // b_i for b_i in b if (next_group // b_i) * a[-1] % p == next_group])

    return unique_groups_count

