def calculate_min_time(maps, scaygers, dist):
    rows, cols = len(maps), len(maps[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(node, target):
        visited[node] = 1
        if node == target:
            return 0

        min_time = float('inf')
        for dx, dy in directions:
            next_node = (x + dx, y + dy)
            if 0 <= next_node[0] < rows and 0 <= next_node[1] < cols and not visited[next_node] and maps[next_node[0]][next_node[1]] != 'O':
                min_time = min(min_time, min_time_helper(next_node))

        visited[node] = 0
        min_time = min(min_time, dist[node] + (1 if min_time % 2 == 0 else 0))

        return min_time

    def min_time_helper(node):
        visited[node] = 1
        min_time = float('inf')
        for dx, dy in directions:
            next_node = (x + dx, y + dy)
            if 0 <= next_node[0] < rows and 0 <= next_node[1] < cols and not visited[next_node] and (maps[next_node[0]][next_node[1]] == 'G' or maps[next_node[0]][next_node[1]] == 'E'):
                min_time = min(min_time, dist[next_node] + dfs(node, next_node))
        visited[node] = 0
        if maps[node[0]][node[1]] == 'G':
            min_time = (min_time - 1) // 2
        if maps[node[0]][node[1]] == 'E':
            min_time = min_time + 1
        return min_time

    # Convert maps to a format suitable for mapping
    maps_array = [[[False for _ in range(cols)] for _ in range(rows)] for _ in range(5)]

    for i in range(rows):
        for j in range(cols):
            if maps[i][j] == 'S':
                maps_array[0][i][j] = True
                x, y = i, j
            elif maps[i][j] == 'G':
                x, y = i, j

    maps_array[1] = [[not maps[i][j] for i in range(rows)] for j in range(cols)]
    for i in range(rows):
        for j in range(cols):
            maps_array[1][i][j] = maps[i][j] == 'S'
            if maps_array[1][i][j]:
                maps_array[2][i][j] = maps[i][j] == 'E'

    maps_array[3] = [[1 if maps[i][j] == '.' or len(maps_array[i][j]) == 1 or maps[i][j] in ['G','E'] else 0 for i in range(rows)] for j in range(cols)]

    dist = [(rows * cols * 2) // 3 for _ in range(rows * cols + 2)]
    dist[0] = 0

    visited = [0] * (rows * cols + 2)
    for u in range(1, len(dist)):
        cur_node = [u // cols, u % cols]
        dist[u] += dfs(cur_node, (x, y))

    return dfs((x, y), (x, y))
